-- Phase 4E: provider-neutral, private client communications foundation.
insert into app_private.permissions(permission_key,description) values
 ('communications.read','Read scoped communication history'),('communications.send','Create approved communication intents'),('communications.templates.read','Read communication templates'),('communications.templates.manage','Manage communication template lifecycle'),('communications.inbound.read','Read scoped inbound messages'),('communications.inbound.review','Review inbound messages'),('communications.integration.manage','Manage communications integration') on conflict do nothing;
insert into app_private.role_permissions(role_id,permission_key) select r.role_id,p.permission_key from app_private.roles r cross join app_private.permissions p where r.role_key='director_admin' and p.permission_key like 'communications.%' on conflict do nothing;
insert into app_private.role_permissions(role_id,permission_key) select r.role_id,p.permission_key from app_private.roles r join app_private.permissions p on p.permission_key in('communications.read','communications.send','communications.templates.read','communications.inbound.read','communications.inbound.review') where r.role_key in('operations_manager','office_admin') on conflict do nothing;

insert into app_private.configuration_definitions(configuration_key,description,value_type,is_required,default_value) values
 ('communications.default-fallback-order','Provider-neutral outbound channel order','json',true,'{"channels":["whatsapp","sms","email"]}'),('communications.mode','Outbound safety mode','string',true,'"capture"'),('communications.test-recipient-allowlist','Approved non-production destinations','json',true,'{"recipients":[]}'),('communications.max-retries','Maximum transient provider retries','number',true,'3'),('communications.callback-max-bytes','Maximum callback payload bytes','number',true,'65536') on conflict do nothing;

create table app_private.communication_templates(
 communication_template_id uuid primary key default gen_random_uuid(),template_key text not null,channel text not null check(channel in('whatsapp','sms','email')),communication_type text not null check(communication_type in('collection_reminder','route_change_notice','financial_notice','general_service_notice','test_message')),language text not null default 'english',version integer not null check(version>0),subject_template text,body_template text not null,variables_schema jsonb not null default '[]' check(jsonb_typeof(variables_schema)='array'),lifecycle_status text not null default 'draft' check(lifecycle_status in('draft','approved','active','retired')),created_by uuid references auth.users,approved_by uuid references auth.users,approved_at timestamptz,created_at timestamptz not null default now(),unique(template_key,channel,language,version),check(channel<>'email' or subject_template is not null));
create unique index communication_template_active_idx on app_private.communication_templates(template_key,channel,language) where lifecycle_status='active';
create table app_private.communication_suppressions(communication_suppression_id uuid primary key default gen_random_uuid(),client_contact_id uuid not null references app_private.client_contacts,channel text not null check(channel in('whatsapp','sms','email')),category text not null default 'operational' check(category in('operational','marketing')),reason text not null,created_by uuid references auth.users,created_at timestamptz not null default now(),revoked_at timestamptz,revoked_by uuid references auth.users);
create unique index communication_suppression_active_idx on app_private.communication_suppressions(client_contact_id,channel,category) where revoked_at is null;
create table app_private.communication_intents(
 communication_intent_id uuid primary key default gen_random_uuid(),communication_type text not null check(communication_type in('collection_reminder','route_change_notice','financial_notice','general_service_notice','test_message')),client_id uuid not null references app_private.clients,client_service_id uuid references app_private.client_services,route_operation_id uuid references app_private.route_operations,source_domain text not null,source_reference text not null,service_region_id uuid not null references app_private.service_regions,template_key text not null,template_version integer not null,priority text not null default 'normal' check(priority in('low','normal','high','urgent')),requested_at timestamptz not null default now(),requested_by uuid references auth.users,lifecycle_status text not null default 'created' check(lifecycle_status in('created','eligibility_pending','ready','sending','delivered','partially_delivered','failed','cancelled','suppressed','archived')),correlation_id uuid not null,idempotency_identity text not null,scheduled_at timestamptz,variables jsonb not null default '{}' check(jsonb_typeof(variables)='object'),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(source_domain,source_reference,communication_type,idempotency_identity));
create index communication_intent_region_status_idx on app_private.communication_intents(service_region_id,lifecycle_status,requested_at desc);
create table app_private.communication_attempts(
 communication_attempt_id uuid primary key default gen_random_uuid(),communication_intent_id uuid not null references app_private.communication_intents,channel text not null check(channel in('whatsapp','sms','email')),provider text not null,client_contact_id uuid references app_private.client_contacts,recipient_snapshot jsonb not null check(jsonb_typeof(recipient_snapshot)='object'),rendered_subject text,rendered_body text not null,template_key text not null,template_version integer not null,started_at timestamptz not null default now(),provider_message_id text,lifecycle_status text not null check(lifecycle_status in('pending','sending','accepted','sent','delivered','failed_temporary','failed_permanent','rejected','cancelled','superseded')),failure_classification text,retry_count integer not null default 0,accepted_at timestamptz,sent_at timestamptz,delivered_at timestamptz,correlation_id uuid not null,created_at timestamptz not null default now(),unique(communication_intent_id,channel,retry_count));
create unique index communication_provider_message_idx on app_private.communication_attempts(provider,provider_message_id) where provider_message_id is not null;
create table app_private.inbound_messages(
 inbound_message_id uuid primary key default gen_random_uuid(),provider text not null,channel text not null check(channel in('whatsapp','sms','email')),provider_message_id text not null,sender_snapshot jsonb not null check(jsonb_typeof(sender_snapshot)='object'),received_at timestamptz not null,content_text text,content_type text not null default 'text',matched_client_id uuid references app_private.clients,matched_contact_id uuid references app_private.client_contacts,matched_client_service_id uuid references app_private.client_services,service_region_id uuid references app_private.service_regions,match_classification text not null check(match_classification in('matched','ambiguous','unmatched')),recognized_command text check(recognized_command in('skip','unknown')),processing_status text not null default 'new' check(processing_status in('new','recognized','needs_review','processed','ignored')),correlation_id uuid not null,created_at timestamptz not null default now(),unique(provider,provider_message_id));
create table app_private.communication_provider_health(provider text not null,channel text not null check(channel in('whatsapp','sms','email')),health_status text not null check(health_status in('healthy','degraded','unhealthy','authentication_required','disabled','unknown')),summary text not null,last_success_at timestamptz,last_failure_at timestamptz,updated_at timestamptz not null default now(),primary key(provider,channel));

alter table app_private.communication_templates enable row level security;alter table app_private.communication_suppressions enable row level security;alter table app_private.communication_intents enable row level security;alter table app_private.communication_attempts enable row level security;alter table app_private.inbound_messages enable row level security;alter table app_private.communication_provider_health enable row level security;
revoke all on app_private.communication_templates,app_private.communication_suppressions,app_private.communication_intents,app_private.communication_attempts,app_private.inbound_messages,app_private.communication_provider_health from public,anon,authenticated;
grant all on app_private.communication_templates,app_private.communication_suppressions,app_private.communication_intents,app_private.communication_attempts,app_private.inbound_messages,app_private.communication_provider_health to service_role;

create or replace function app_private.communications_require(p_actor uuid,p_permission text,p_region uuid)returns void language plpgsql security definer set search_path='' as $$begin if not app_private.user_has_region_permission(p_actor,p_permission,p_region)then raise exception 'region_denied' using errcode='42501';end if;end$$;
create or replace function app_private.communications_has_permission(p_actor uuid,p_permission text)returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.user_profiles profile join app_private.user_roles ur on ur.user_id=profile.user_id join app_private.role_permissions rp on rp.role_id=ur.role_id where profile.user_id=p_actor and profile.is_active and rp.permission_key=p_permission)$$;
create or replace function app_private.communication_eligibility(p_client uuid,p_type text)returns jsonb language plpgsql security definer set search_path='' as $$declare c app_private.client_contacts%rowtype;channels jsonb:='[]'::jsonb;begin perform p_type;select * into c from app_private.client_contacts where client_id=p_client and is_primary and is_active order by created_at limit 1;if c.client_contact_id is null then return jsonb_build_object('recipientAvailable',false,'eligibleChannels','[]'::jsonb,'suppressionState','unavailable','language','english');end if;if c.mobile_e164 is not null and not exists(select 1 from app_private.communication_suppressions s where s.client_contact_id=c.client_contact_id and s.channel='whatsapp'and s.category='operational'and s.revoked_at is null)then channels:=channels||'"whatsapp"'::jsonb;end if;if c.mobile_e164 is not null and not exists(select 1 from app_private.communication_suppressions s where s.client_contact_id=c.client_contact_id and s.channel='sms'and s.category='operational'and s.revoked_at is null)then channels:=channels||'"sms"'::jsonb;end if;if c.email is not null and not exists(select 1 from app_private.communication_suppressions s where s.client_contact_id=c.client_contact_id and s.channel='email'and s.category='operational'and s.revoked_at is null)then channels:=channels||'"email"'::jsonb;end if;return jsonb_build_object('recipientAvailable',jsonb_array_length(channels)>0,'contactId',c.client_contact_id,'eligibleChannels',channels,'preferredFallbackOrder',channels,'suppressionState',case when jsonb_array_length(channels)>0 then'allowed'else'suppressed'end,'language',c.preferred_language,'mobile',c.mobile_e164,'email',c.email,'categoryAllowed',true);end$$;
create or replace function api.communication_create_intent(p_actor uuid,p_body jsonb,p_correlation uuid,p_idempotency text)returns jsonb language plpgsql security definer set search_path='' as $$declare region uuid;i app_private.communication_intents%rowtype;eligibility jsonb;begin select sc.service_region_id into region from app_private.client_services cs join app_private.service_configurations sc using(client_service_id)where cs.client_id=(p_body->>'clientId')::uuid and sc.effective_to is null order by sc.effective_from desc limit 1;perform app_private.communications_require(p_actor,'communications.send',region);if p_body->>'communicationType'<>'test_message'and p_body->>'sourceDomain'='manual'then raise exception 'approved_source_required' using errcode='22023';end if;eligibility:=app_private.communication_eligibility((p_body->>'clientId')::uuid,p_body->>'communicationType');insert into app_private.communication_intents(communication_type,client_id,client_service_id,source_domain,source_reference,service_region_id,template_key,template_version,priority,requested_by,lifecycle_status,correlation_id,idempotency_identity,scheduled_at,variables)values(p_body->>'communicationType',(p_body->>'clientId')::uuid,nullif(p_body->>'clientServiceId','')::uuid,p_body->>'sourceDomain',p_body->>'sourceReference',region,p_body->>'templateKey',coalesce((p_body->>'templateVersion')::integer,1),coalesce(p_body->>'priority','normal'),p_actor,case when(eligibility->>'recipientAvailable')::boolean then'ready'else'suppressed'end,p_correlation,p_idempotency,nullif(p_body->>'scheduledAt','')::timestamptz,coalesce(p_body->'variables','{}'))on conflict(source_domain,source_reference,communication_type,idempotency_identity)do update set idempotency_identity=excluded.idempotency_identity returning * into i;insert into app_private.business_audit_facts(action_key,actor_id,module_key,target_type,target_id,correlation_id,after_state)values(case when i.communication_type='test_message'then'communications.test_send_requested'else'communications.manual_send_requested'end,p_actor,'communications','communication-intent',i.communication_intent_id,p_correlation,jsonb_build_object('type',i.communication_type,'status',i.lifecycle_status));insert into app_private.outbox_events(producer_module,event_name,event_version,aggregate_type,aggregate_id,payload,correlation_id,actor_kind,actor_id,occurred_at)values('communications','Communications.IntentCreated',1,'communication-intent',i.communication_intent_id,jsonb_build_object('intentId',i.communication_intent_id,'communicationType',i.communication_type,'clientId',i.client_id),p_correlation,'user',p_actor::text,now())on conflict do nothing;return to_jsonb(i)||jsonb_build_object('eligibility',eligibility);end$$;
create or replace function api.communication_record_attempt(p_intent uuid,p_channel text,p_provider text,p_recipient jsonb,p_subject text,p_body text,p_status text,p_provider_message text,p_failure text,p_retry integer,p_correlation uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare i app_private.communication_intents%rowtype;a app_private.communication_attempts%rowtype;begin select * into i from app_private.communication_intents where communication_intent_id=p_intent for update;if i.lifecycle_status in('delivered','cancelled','archived')then return to_jsonb(i);end if;insert into app_private.communication_attempts(communication_intent_id,channel,provider,client_contact_id,recipient_snapshot,rendered_subject,rendered_body,template_key,template_version,lifecycle_status,provider_message_id,failure_classification,retry_count,correlation_id,accepted_at,delivered_at)values(p_intent,p_channel,p_provider,nullif(p_recipient->>'contactId','')::uuid,p_recipient,p_subject,p_body,i.template_key,i.template_version,p_status,p_provider_message,p_failure,p_retry,p_correlation,case when p_status in('accepted','sent','delivered')then now()end,case when p_status='delivered'then now()end)returning * into a;update app_private.communication_intents set lifecycle_status=case when p_status='delivered'then'delivered'when p_status in('failed_permanent','rejected')then'sending'else'sending'end,updated_at=now()where communication_intent_id=p_intent;if p_status='delivered'then insert into app_private.outbox_events(producer_module,event_name,event_version,aggregate_type,aggregate_id,payload,correlation_id,actor_kind,actor_id,occurred_at)values('communications','Communications.Delivered',1,'communication-intent',p_intent,jsonb_build_object('intentId',p_intent,'channel',p_channel),p_correlation,'system','communications-dispatcher',now());end if;return to_jsonb(a);end$$;
create or replace function api.communication_fail_intent(p_intent uuid,p_classification text,p_correlation uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare i app_private.communication_intents%rowtype;begin update app_private.communication_intents set lifecycle_status='failed',updated_at=now()where communication_intent_id=p_intent and lifecycle_status not in('delivered','cancelled','archived')returning * into i;if i.communication_intent_id is not null then insert into app_private.outbox_events(producer_module,event_name,event_version,aggregate_type,aggregate_id,payload,correlation_id,actor_kind,actor_id,occurred_at)values('communications','Communications.Failed',1,'communication-intent',p_intent,jsonb_build_object('intentId',p_intent,'classification',p_classification),p_correlation,'system','communications-dispatcher',now());end if;return to_jsonb(i);end$$;
create or replace function api.communication_delivery_callback(p_provider text,p_message text,p_status text,p_occurred timestamptz)returns jsonb language plpgsql security definer set search_path='' as $$declare a app_private.communication_attempts%rowtype;rank_old integer;rank_new integer;begin select * into a from app_private.communication_attempts where provider=p_provider and provider_message_id=p_message for update;if a.communication_attempt_id is null then raise exception 'not_found' using errcode='P0002';end if;rank_old:=case a.lifecycle_status when'accepted'then 1 when'sent'then 2 when'delivered'then 3 else 0 end;rank_new:=case p_status when'accepted'then 1 when'sent'then 2 when'delivered'then 3 when'read'then 4 else 0 end;if rank_new>rank_old then update app_private.communication_attempts set lifecycle_status=case when p_status='read'then'delivered'else p_status end,sent_at=case when p_status in('sent','delivered','read')then coalesce(sent_at,p_occurred)else sent_at end,delivered_at=case when p_status in('delivered','read')then coalesce(delivered_at,p_occurred)else delivered_at end where communication_attempt_id=a.communication_attempt_id returning * into a;if p_status in('delivered','read')then update app_private.communication_intents set lifecycle_status='delivered',updated_at=now()where communication_intent_id=a.communication_intent_id;end if;end if;return to_jsonb(a);end$$;
create or replace function api.communication_ingest_inbound(p_provider text,p_channel text,p_message text,p_sender text,p_received timestamptz,p_content text,p_correlation uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare ids uuid[];contact uuid;client uuid;service uuid;region uuid;classification text;command text;m app_private.inbound_messages%rowtype;begin select array_agg(client_contact_id)into ids from app_private.client_contacts where is_active and((p_channel in('whatsapp','sms')and mobile_e164=p_sender)or(p_channel='email'and lower(email)=lower(p_sender)));classification:=case when coalesce(array_length(ids,1),0)=1 then'matched'when coalesce(array_length(ids,1),0)>1 then'ambiguous'else'unmatched'end;if classification='matched'then contact:=ids[1];select client_id into client from app_private.client_contacts where client_contact_id=contact;select cs.client_service_id,sc.service_region_id into service,region from app_private.client_services cs join app_private.service_configurations sc using(client_service_id)where cs.client_id=client and cs.lifecycle_status='active'and sc.effective_to is null order by cs.created_at limit 1;end if;command:=case when lower(btrim(p_content))='skip'then'skip'else'unknown'end;insert into app_private.inbound_messages(provider,channel,provider_message_id,sender_snapshot,received_at,content_text,matched_client_id,matched_contact_id,matched_client_service_id,service_region_id,match_classification,recognized_command,processing_status,correlation_id)values(p_provider,p_channel,p_message,jsonb_build_object('sender',p_sender),p_received,p_content,client,contact,service,region,classification,command,case when classification='matched'and command='skip'then'recognized'else'needs_review'end,p_correlation)on conflict(provider,provider_message_id)do update set provider_message_id=excluded.provider_message_id returning * into m;insert into app_private.outbox_events(producer_module,event_name,event_version,aggregate_type,aggregate_id,payload,correlation_id,actor_kind,actor_id,occurred_at)values('communications','Communications.InboundMessageReceived',1,'inbound-message',m.inbound_message_id,jsonb_build_object('inboundMessageId',m.inbound_message_id,'matchClassification',m.match_classification),p_correlation,'system','communications-webhook',now())on conflict do nothing;if m.recognized_command='skip'and m.match_classification='matched'then insert into app_private.outbox_events(producer_module,event_name,event_version,aggregate_type,aggregate_id,payload,correlation_id,actor_kind,actor_id,occurred_at)values('communications','Communications.InboundCommandRecognized',1,'inbound-message',m.inbound_message_id,jsonb_build_object('inboundMessageId',m.inbound_message_id,'command','skip','clientServiceId',m.matched_client_service_id),p_correlation,'system','communications-command-parser',now())on conflict do nothing;end if;return to_jsonb(m);end$$;
create or replace function api.communication_list(p_actor uuid,p_query jsonb default '{}')returns jsonb language plpgsql security definer set search_path='' as $$begin if not app_private.communications_has_permission(p_actor,'communications.read')then raise exception 'permission_denied' using errcode='42501';end if;return jsonb_build_object('items',(select coalesce(jsonb_agg(jsonb_build_object('intentId',i.communication_intent_id,'clientId',i.client_id,'clientName',c.display_name,'clientServiceId',i.client_service_id,'communicationType',i.communication_type,'status',i.lifecycle_status,'requestedAt',i.requested_at,'templateKey',i.template_key,'templateVersion',i.template_version,'attempts',(select coalesce(jsonb_agg(jsonb_build_object('channel',a.channel,'provider',a.provider,'status',a.lifecycle_status,'failureClassification',a.failure_classification)order by a.started_at),'[]')from app_private.communication_attempts a where a.communication_intent_id=i.communication_intent_id))order by i.requested_at desc),'[]')from app_private.communication_intents i join app_private.clients c using(client_id)where app_private.user_has_region_permission(p_actor,'communications.read',i.service_region_id)and(nullif(p_query->>'clientId','')is null or i.client_id=(p_query->>'clientId')::uuid)));end$$;
create or replace function api.communication_inbound_list(p_actor uuid)returns jsonb language plpgsql security definer set search_path='' as $$begin if not app_private.communications_has_permission(p_actor,'communications.inbound.read')then raise exception 'permission_denied' using errcode='42501';end if;return jsonb_build_object('items',(select coalesce(jsonb_agg(jsonb_build_object('inboundMessageId',m.inbound_message_id,'channel',m.channel,'receivedAt',m.received_at,'clientId',m.matched_client_id,'matchClassification',m.match_classification,'recognizedCommand',m.recognized_command,'status',m.processing_status)order by m.received_at desc),'[]')from app_private.inbound_messages m where(m.service_region_id is null and app_private.user_has_global_permission(p_actor,'communications.inbound.read'))or(m.service_region_id is not null and app_private.user_has_region_permission(p_actor,'communications.inbound.read',m.service_region_id))));end$$;
create or replace function api.communication_templates(p_actor uuid)returns jsonb language plpgsql security definer set search_path='' as $$begin if not app_private.user_has_global_permission(p_actor,'communications.templates.read')then raise exception 'permission_denied' using errcode='42501';end if;return jsonb_build_object('items',(select coalesce(jsonb_agg(jsonb_build_object('templateId',communication_template_id,'templateKey',template_key,'channel',channel,'communicationType',communication_type,'language',language,'version',version,'status',lifecycle_status,'variablesSchema',variables_schema)order by template_key,channel,version desc),'[]')from app_private.communication_templates));end$$;
create or replace function api.communication_template_transition(p_actor uuid,p_template uuid,p_status text,p_reason text,p_correlation uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare t app_private.communication_templates%rowtype;allowed boolean;begin if not app_private.user_has_global_permission(p_actor,'communications.templates.manage')then raise exception 'permission_denied' using errcode='42501';end if;if length(btrim(coalesce(p_reason,'')))<3 then raise exception 'reason_required' using errcode='22023';end if;select * into t from app_private.communication_templates where communication_template_id=p_template for update;if t.communication_template_id is null then raise exception 'not_found' using errcode='P0002';end if;allowed:=(t.lifecycle_status='draft'and p_status='approved')or(t.lifecycle_status='approved'and p_status='active')or(t.lifecycle_status='active'and p_status='retired');if not allowed then raise exception 'invalid_template_transition' using errcode='55000';end if;if p_status='active'then update app_private.communication_templates set lifecycle_status='retired'where template_key=t.template_key and channel=t.channel and language=t.language and lifecycle_status='active';end if;update app_private.communication_templates set lifecycle_status=p_status,approved_by=case when p_status in('approved','active')then p_actor else approved_by end,approved_at=case when p_status in('approved','active')then now()else approved_at end where communication_template_id=p_template returning * into t;insert into app_private.business_audit_facts(action_key,actor_id,module_key,target_type,target_id,correlation_id,after_state)values('communications.template_'||p_status,p_actor,'communications','communication-template',p_template,p_correlation,jsonb_build_object('status',p_status,'reason',p_reason));return to_jsonb(t);end$$;
create or replace function api.communication_inbound_review(p_actor uuid,p_inbound uuid,p_status text,p_reason text,p_correlation uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare m app_private.inbound_messages%rowtype;begin select * into m from app_private.inbound_messages where inbound_message_id=p_inbound for update;if m.inbound_message_id is null then raise exception 'not_found' using errcode='P0002';end if;if m.service_region_id is null then if not app_private.user_has_global_permission(p_actor,'communications.inbound.review')then raise exception 'permission_denied' using errcode='42501';end if;else perform app_private.communications_require(p_actor,'communications.inbound.review',m.service_region_id);end if;if p_status not in('processed','ignored','needs_review')or length(btrim(coalesce(p_reason,'')))<3 then raise exception 'invalid_review' using errcode='22023';end if;update app_private.inbound_messages set processing_status=p_status where inbound_message_id=p_inbound returning * into m;insert into app_private.business_audit_facts(action_key,actor_id,module_key,target_type,target_id,correlation_id,after_state)values('communications.inbound_reviewed',p_actor,'communications','inbound-message',p_inbound,p_correlation,jsonb_build_object('status',p_status,'reason',p_reason));return to_jsonb(m);end$$;
create or replace function api.communication_cancel(p_actor uuid,p_intent uuid,p_reason text,p_correlation uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare i app_private.communication_intents%rowtype;begin select * into i from app_private.communication_intents where communication_intent_id=p_intent for update;perform app_private.communications_require(p_actor,'communications.send',i.service_region_id);if i.lifecycle_status not in('created','eligibility_pending','ready')then raise exception 'cannot_cancel_sent_intent' using errcode='55000';end if;update app_private.communication_intents set lifecycle_status='cancelled',updated_at=now()where communication_intent_id=p_intent returning * into i;insert into app_private.business_audit_facts(action_key,actor_id,module_key,target_type,target_id,correlation_id,after_state)values('communications.intent_cancelled',p_actor,'communications','communication-intent',p_intent,p_correlation,jsonb_build_object('reason',p_reason));return to_jsonb(i);end$$;
create or replace function api.communication_health(p_actor uuid)returns jsonb language plpgsql security definer set search_path='' as $$begin if not app_private.user_has_global_permission(p_actor,'communications.integration.manage')and not app_private.user_has_global_permission(p_actor,'communications.read')then raise exception 'permission_denied' using errcode='42501';end if;return jsonb_build_object('items',(select coalesce(jsonb_agg(to_jsonb(h)),'[]')from app_private.communication_provider_health h));end$$;

revoke all on function app_private.communications_require(uuid,text,uuid),app_private.communications_has_permission(uuid,text),app_private.communication_eligibility(uuid,text)from public,anon,authenticated;
revoke all on function api.communication_create_intent(uuid,jsonb,uuid,text),api.communication_record_attempt(uuid,text,text,jsonb,text,text,text,text,text,integer,uuid),api.communication_fail_intent(uuid,text,uuid),api.communication_delivery_callback(text,text,text,timestamptz),api.communication_ingest_inbound(text,text,text,text,timestamptz,text,uuid),api.communication_list(uuid,jsonb),api.communication_inbound_list(uuid),api.communication_templates(uuid),api.communication_template_transition(uuid,uuid,text,text,uuid),api.communication_inbound_review(uuid,uuid,text,text,uuid),api.communication_cancel(uuid,uuid,text,uuid),api.communication_health(uuid)from public,anon,authenticated;
grant execute on function api.communication_create_intent(uuid,jsonb,uuid,text),api.communication_list(uuid,jsonb),api.communication_inbound_list(uuid),api.communication_templates(uuid),api.communication_template_transition(uuid,uuid,text,text,uuid),api.communication_inbound_review(uuid,uuid,text,text,uuid),api.communication_cancel(uuid,uuid,text,uuid),api.communication_health(uuid)to service_role;
grant execute on function api.communication_record_attempt(uuid,text,text,jsonb,text,text,text,text,text,integer,uuid),api.communication_fail_intent(uuid,text,uuid),api.communication_delivery_callback(text,text,text,timestamptz),api.communication_ingest_inbound(text,text,text,text,timestamptz,text,uuid)to service_role;

